const activityCatalog=[
{name:'A little of everything',icon:'✧',detail:'Miso wanders, reads, creates, and takes little breaks.'},
{name:'Walking around',icon:'👣',detail:'Exploring the room, one little paw at a time.'},
{name:'Reading',icon:'📖',detail:'Turning the pages of a favorite story.'},
{name:'Knitting',icon:'🧶',detail:'Making a tiny scarf, stitch by stitch.'},
{name:'Watering plants',icon:'🌿',detail:'A sprinkle for the plants and a moment of calm.'},
{name:'Drinking water',icon:'💧',detail:'Lifting a glass for a refreshing sip.'},
{name:'Dancing',icon:'♫',detail:'Little steps, big ears, and a whole lot of joy.'},
{name:'Stretching',icon:'☀',detail:'Reaching up and stretching those little paws.'},
{name:'Painting',icon:'🎨',detail:'Adding a splash of color to a little masterpiece.'},
{name:'Sleeping',icon:'☾',detail:'Curled up on the sofa for a cozy nap.'},
{name:'Eating together',icon:'🍽',detail:'Sharing the meal you chose.'}
];
const routine=['Walking around','Reading','Walking around','Watering plants','Knitting','Drinking water','Dancing','Painting','Stretching','Sleeping'];
function currentActivity(){const g=petGlucose();if(g==='low')return'Snacking';if(g==='high')return'Drinking water';if(activity==='A little of everything')return routine[Math.floor((Date.now()-activityStarted)/13000)%routine.length];if(activity==='Eating together'&&!state.sharedMeal)return'Reading';return activity}
function activityButtons(){return activityCatalog.filter(a=>!['A little of everything','Eating together'].includes(a.name)).map(a=>`<button data-act="${a.name}" title="${a.detail}" aria-label="${a.name}">${a.icon}<span>${a.name}</span></button>`).join('')}
function setActivity(name){if(!activityCatalog.some(a=>a.name===name))return;if(name==='Eating together'&&!state.sharedMeal){toast('Name your meal below, then share it with Miso.');return}activity=name;activityStarted=Date.now();if(page==='home'){drawRoom();document.querySelectorAll('[data-act]').forEach(b=>b.classList.toggle('selected',b.dataset.act===name))}}
function updateActionCaption(a){const meta=activityCatalog.find(x=>x.name===a)||{icon:'🍪',detail:'A snack break. Follow your personal low-glucose care plan.'};const title=$('#action-title'),detail=$('#action-detail'),icon=$('#action-icon');if(title)title.textContent=a==='Eating together'?'Eating '+state.sharedMeal.name:a==='Snacking'?'Miso is having a snack':'Miso is '+a.toLowerCase();if($('#room')?._misoPose?.travel&&a!=='Walking around'&&title)title.textContent='Walking over to '+(a==='Eating together'?'share your meal':a.toLowerCase());if(detail)detail.textContent=petGlucose()==='high'?'A water break · Follow your personal care plan.':a==='Eating together'?'Taking little bites, just like you.':meta.detail;if(icon)icon.textContent=meta.icon;if(title)title.textContent=title.textContent.replaceAll('Miso',state.characterName)}
function openActivities(){showModal(`<div class="eyebrow">MISO’S EVERYDAY MOMENTS</div><h2>A whole little life.</h2><p>Pick an activity, or let Miso follow a little routine.</p><div class="activity-picker">${activityCatalog.map(a=>`<button class="${activity===a.name?'selected':''}" data-act="${a.name}"><b>${a.icon}</b><span>${a.name}<small>${a.detail}</small></span></button>`).join('')}</div>`)}
function bindWorldInteractions(){const canvas=$('#room');canvas.onclick=e=>{const rect=canvas.getBoundingClientRect(),x=(e.clientX-rect.left)*480/rect.width,y=(e.clientY-rect.top)*310/rect.height;if(x<115&&y>155)setActivity('Watering plants');else if(x>350&&y>180)setActivity(state.sharedMeal?'Eating together':'Drinking water');else if(x>325&&y<175)setActivity('Reading');else if(x>150&&x<350&&y>170)setActivity('Sleeping');else setActivity('Walking around')};}
function isEligibleMealEvent(event,now=Date.now()){
// No live t:slim adapter is installed. Only explicit demo fixtures can be eligible here.
return !!event&&typeof event.id==='string'&&event.id.length>0&&event.source==='demo'&&event.kind==='meal_bolus'&&event.bolusDelivered===true&&Number.isFinite(event.carbs)&&event.carbs>0&&Number.isFinite(event.occurredAt)&&Number.isFinite(event.receivedAt)&&now-event.occurredAt>=0&&now-event.occurredAt<=600000&&now-event.receivedAt>=0&&now-event.receivedAt<=600000&&!state.usedMealEvents.includes(event.id);
}
function eligibleMealEvent(){return state.mealEvents.slice().reverse().find(e=>isEligibleMealEvent(e))||null}
function openEventSimulator(){showModal(`<div class="eyebrow">TEST ONLY · NO DEVICE ACTION</div><h2>Test the 10-minute gate.</h2><p>t:slim is not connected. These fixtures simulate read-only incoming events and never deliver insulin.</p><label class="field-label" for="event-kind">Incoming event</label><select id="event-kind"><option value="meal">Meal bolus delivered + carb entry</option><option value="correction">Correction bolus · no carbs</option><option value="carbs">Carb entry · no delivered bolus</option><option value="pending">Carbs + bolus requested · not delivered</option></select><label class="field-label" for="event-age">How long ago?</label><select id="event-age"><option value="0">Just now</option><option value="5">5 minutes ago</option><option value="11">11 minutes ago · should stay locked</option></select><div class="notice">One eligible event unlocks one timer. Old events, correction-only boluses, and carb-only entries stay locked.</div><div class="modal-actions"><button class="primary" id="receive-demo-event">Receive simulated event</button></div>`);$('#receive-demo-event').onclick=()=>{const kind=$('#event-kind').value,age=Number($('#event-age').value),time=Date.now()-age*60000;state.mealEvents=[{id:crypto.randomUUID(),source:'demo',kind:kind==='correction'?'correction_bolus':'meal_bolus',carbs:kind==='correction'?0:45,bolusDelivered:['meal','correction'].includes(kind),occurredAt:time,receivedAt:time}];save();modal.close();go('home');toast(eligibleMealEvent()?'Simulated meal event received. You can choose a timer.':'Simulated event received. It does not qualify for a timer.')};}
function mealCard(){return `<section class="card meal-card"><div class="meal-heading"><span class="meal-spark">✦</span><div><div class="eyebrow">A LITTLE MEAL, TOGETHER</div><h2>What’s on your plate?</h2><p>Name your meal. On-device AI picks an illustration, then Miso takes a seat and joins you.</p></div><span class="ai-tag">ON-DEVICE AI</span></div><form id="meal-form" class="meal-input-row"><label class="sr-only" for="meal-name">Name of your meal</label><input id="meal-name" type="text" maxlength="120" placeholder="e.g. spaghetti bolognese, sushi, avocado toast…" value="${escapeHTML(state.sharedMeal?.name||'')}" required><button class="primary" id="illustrate-meal" type="submit">Illustrate my meal ✦</button></form><div class="meal-examples">Try <button data-meal-example="Margherita pizza">pizza</button><button data-meal-example="Salmon sushi">sushi</button><button data-meal-example="Pancakes with berries">pancakes & berries</button><button class="text-link" id="manual-meal" type="button">Choose illustration myself</button></div><p id="meal-ai-status" class="meal-ai-status" role="status">First use downloads a small AI model (~25 MB). Meal text stays on your device. No carb or insulin estimates.</p><div id="meal-result"></div>${state.sharedMeal?`<div class="shared-meal"><span>🍽</span><p>Miso’s plate: <b>${escapeHTML(state.sharedMeal.name)}</b><small>${escapeHTML(window.MellowMealAI.foods.find(f=>f.id===state.sharedMeal.food)?.name||'Your own plate')} illustration</small></p><button class="secondary" id="eat-again">Eat together ↗</button></div>`:''}</section>`}
let mealJob=0;
function bindMealCard(){const form=$('#meal-form');if(!form)return;form.onsubmit=async e=>{e.preventDefault();const name=$('#meal-name').value.trim();if(!name){toast('Tell Miso what you’re eating.');return}const job=++mealJob;const button=$('#illustrate-meal');button.disabled=true;button.textContent='Finding your meal…';$('#meal-result').innerHTML='';const status=$('#meal-ai-status');try{const result=await window.MellowMealAI.match(name,message=>{if(job===mealJob&&page==='home')status.textContent=message});if(job!==mealJob||page!=='home')return;status.textContent='AI picked an illustration. Check the match or choose another before sharing.';mealResult(name,result.food.id,true)}catch(error){if(job!==mealJob||page!=='home')return;status.textContent='The AI model couldn’t load. You can still choose a meal illustration below.';mealResult(name,'custom',false)}finally{if(job===mealJob&&page==='home'){button.disabled=false;button.textContent='Illustrate my meal ✦'}}};$('#manual-meal').onclick=()=>{mealJob++;const name=$('#meal-name').value.trim();if(!name){toast('Name your meal first.');$('#meal-name').focus();return}$('#illustrate-meal').disabled=false;$('#illustrate-meal').textContent='Illustrate my meal ✦';$('#meal-ai-status').textContent='Choose the illustration that best matches your meal.';mealResult(name,'custom',false)};document.querySelectorAll('[data-meal-example]').forEach(b=>b.onclick=()=>{$('#meal-name').value=b.dataset.mealExample;form.requestSubmit()});if($('#eat-again'))$('#eat-again').onclick=()=>setActivity('Eating together')}
function mealResult(name,food,usedAI){$('#meal-result').innerHTML=`<div class="meal-result-inner"><canvas id="meal-preview" width="300" height="200" aria-label="Meal illustration preview"></canvas><div><div class="eyebrow">${usedAI?'AI ILLUSTRATION MATCH':'YOUR ILLUSTRATION CHOICE'}</div><h3>${escapeHTML(name)}</h3><label for="meal-illustration" class="sr-only">Meal illustration</label><select id="meal-illustration">${window.MellowMealAI.foods.map(f=>`<option value="${f.id}" ${f.id===food?'selected':''}>${f.name}</option>`).join('')}</select><button class="primary" id="share-meal">Share this meal with Miso →</button></div></div>`;const draw=()=>{const c=$('#meal-preview').getContext('2d');c.clearRect(0,0,300,200);c.save();c.scale(2.1,2.1);c.translate(71,48);drawMeal(c,$('#meal-illustration').value,0);c.restore()};draw();$('#meal-illustration').onchange=draw;$('#share-meal').onclick=()=>{state.sharedMeal={name,food:$('#meal-illustration').value,matchedBy:usedAI?'on-device-ai':'manual',createdAt:Date.now()};recordSharedMeal(state.sharedMeal);save();activity='Eating together';activityStarted=Date.now();home();toast('A seat for two. Miso is joining you for '+name+' ♡')};}
